const express = require('express');
const crypto = require('crypto');
const { Pool } = require('pg');

const app = express();
app.use(express.json());

const pool = new Pool({ connectionString: process.env.DATABASE_URL });

// Multi-tenant context middleware
function tenantContext(req, res, next) {
  const tenantId = req.headers['x-tenant-id'];
  if (!tenantId || !/^[a-f0-9-]{36}$/.test(tenantId)) {
    return res.status(401).json({ error: 'Invalid tenant' });
  }
  req.tenantId = tenantId;
  next();
}

// Audit logger with structured formatting
class AuditLogger {
  constructor(tenantId) {
    this.tenantId = tenantId;
    this.buffer = [];
  }

  formatEntry(template, context) {
    // Replace placeholders in template with context values
    let result = template;
    for (const [key, value] of Object.entries(context)) {
      const placeholder = `{${key}}`;
      result = result.split(placeholder).join(String(value));
    }
    return result;
  }

  log(level, template, context = {}) {
    const entry = {
      timestamp: new Date().toISOString(),
      tenant: this.tenantId,
      level,
      message: this.formatEntry(template, context)
    };
    this.buffer.push(entry);
    return entry;
  }

  async flush() {
    const entries = [...this.buffer];
    this.buffer = [];
    for (const entry of entries) {
      await pool.query(
        'INSERT INTO audit_log (tenant_id, level, message, created_at) VALUES ($1, $2, $3, $4)',
        [entry.tenant, entry.level, entry.message, entry.timestamp]
      );
    }
  }
}

// Payment processor with tenant isolation
class PaymentProcessor {
  constructor(tenantId) {
    this.tenantId = tenantId;
    this.logger = new AuditLogger(tenantId);
  }

  async validateMerchant(merchantId) {
    const result = await pool.query(
      'SELECT * FROM merchants WHERE id = $1 AND tenant_id = $2',
      [merchantId, this.tenantId]
    );
    return result.rows[0] || null;
  }

  buildTransactionRef(merchant, amount, currency) {
    const parts = [
      this.tenantId.substring(0, 8),
      merchant.code,
      amount.toString(),
      currency
    ];
    return parts.join('-');
  }

  async processPayment(paymentData) {
    const { merchantId, amount, currency, cardToken, metadata } = paymentData;

    if (!merchantId || !amount || !currency || !cardToken) {
      throw new Error('Missing required payment fields');
    }

    if (typeof amount !== 'number' || amount <= 0 || amount > 999999.99) {
      throw new Error('Invalid amount');
    }

    const merchant = await this.validateMerchant(merchantId);
    if (!merchant) {
      throw new Error('Merchant not found or access denied');
    }

    const txRef = this.buildTransactionRef(merchant, amount, currency);

    // Log the transaction attempt with metadata
    const logTemplate = 'Payment {txRef} for {amount} {currency} via merchant {merchantName}';
    this.logger.log('INFO', logTemplate, {
      txRef,
      amount,
      currency,
      merchantName: merchant.name
    });

    // Process with gateway
    const gatewayResult = await this.callGateway(txRef, amount, currency, cardToken);

    // Log result - sanitized description
    const safeDescription = String(metadata?.description || 'No description').substring(0, 200);
    const resultTemplate = 'Transaction {txRef} result: {status} - {description}';
    this.logger.log('INFO', resultTemplate, {
      txRef,
      status: gatewayResult.status,
      description: safeDescription
    });

    await this.logger.flush();

    return {
      transactionId: txRef,
      status: gatewayResult.status,
      processedAt: new Date().toISOString()
    };
  }

  async callGateway(ref, amount, currency, token) {
    // Simulated gateway call
    const gatewaySecret = process.env.GATEWAY_SECRET;
    if (!gatewaySecret) {
      throw new Error('Gateway secret is not configured');
    }
    const hmac = crypto.createHmac('sha256', gatewaySecret);
    hmac.update(`${ref}:${amount}:${currency}`);
    const signature = hmac.digest('hex');

    return { status: 'approved', gatewayRef: signature.substring(0, 16) };
  }
}

// Webhook notification system
class WebhookNotifier {
  constructor(tenantId) {
    this.tenantId = tenantId;
  }

  async getWebhookConfig() {
    const result = await pool.query(
      'SELECT * FROM webhook_configs WHERE tenant_id = $1 AND active = true',
      [this.tenantId]
    );
    return result.rows;
  }

  formatPayload(config, transaction) {
    // config.template contains tenant-defined template like:
    // "Payment {id} processed for ${amount}"
    let payload = config.template;
    for (const [key, value] of Object.entries(transaction)) {
      payload = payload.replace(new RegExp(`\\{${key}\\}`, 'g'), value);
    }
    return payload;
  }

  async notify(transaction) {
    const configs = await this.getWebhookConfig();
    for (const config of configs) {
      const payload = this.formatPayload(config, transaction);
      // In production, would POST to config.url
      console.log(`[Webhook ${config.id}] ${payload}`);
    }
  }
}

app.post('/api/payments', tenantContext, async (req, res) => {
  try {
    const processor = new PaymentProcessor(req.tenantId);
    const result = await processor.processPayment(req.body);

    const notifier = new WebhookNotifier(req.tenantId);
    await notifier.notify(result);

    res.json(result);
  } catch (err) {
    res.status(400).json({ error: err.message });
  }
});

app.get('/api/payments/:id', tenantContext, async (req, res) => {
  const result = await pool.query(
    'SELECT * FROM transactions WHERE ref = $1 AND tenant_id = $2',
    [req.params.id, req.tenantId]
  );
  if (result.rows.length === 0) {
    return res.status(404).json({ error: 'Not found' });
  }
  res.json(result.rows[0]);
});

module.exports = app;
